// --- LÓGICA CORRIGIDA PARA O SEU JSON ---

// 1. Pega o JSON exato que você postou
const apiNode = $('API - Buscar Grupo').first();
const apiJson = apiNode ? apiNode.json : {};

// Navega até o array 'participants' baseado na estrutura: { data: { participants: [...] } }
let participants = [];
if (apiJson.data && apiJson.data.participants) {
    participants = apiJson.data.participants;
} else if (Array.isArray(apiJson)) {
    // Caso a API retorne o array direto em algumas situações
    participants = apiJson;
}

// 2. Cria a Lista de Referência (Set)
// ATENÇÃO: Usamos 'phoneNumber' e não 'id', pois seu ID é um LID (@lid)
const groupNumbers = new Set();

for (const p of participants) {
    // Verifica se tem phoneNumber (ex: "551199999999@s.whatsapp.net")
    if (p.phoneNumber) {
        // Pega apenas os números antes do @
        const cleanNum = p.phoneNumber.split('@')[0].replace(/\D/g, '');
        groupNumbers.add(cleanNum);
    }
}

// 3. Itera sobre a planilha
const results = [];

for (const item of items) {
    const row = item.json;
    const originalPhone = row.Telefone ? row.Telefone.toString() : '';

    // LIMPEZA: Remove tudo que não for número da planilha
    let cleanPhone = originalPhone.replace(/\D/g, '');

    // Ajuste DDI Brasil (55)
    if (cleanPhone.length >= 10 && cleanPhone.length <= 11) {
        cleanPhone = '55' + cleanPhone;
    }
    if (cleanPhone.startsWith('0')) {
        cleanPhone = cleanPhone.substring(1);
    }

    // LÓGICA DE VERIFICAÇÃO (Tentativa e Erro)
    let status = "NÃO ENCONTRADO";
    let log = "Falso";

    if (cleanPhone.length > 7) {
        // A. Busca Exata
        if (groupNumbers.has(cleanPhone)) {
            status = "NO GRUPO";
            log = "Match Exato";
        } 
        // B. Tenta removendo o 9º dígito (para bater com 13 digitos)
        else if (cleanPhone.length === 13 && cleanPhone.startsWith('55')) {
             const noNine = cleanPhone.slice(0, 4) + cleanPhone.slice(5);
             if (groupNumbers.has(noNine)) {
                 status = "NO GRUPO";
                 log = "Match sem 9 dígito";
             }
        }
        // C. Tenta adicionando o 9º dígito (para bater com 12 digitos)
        else if (cleanPhone.length === 12 && cleanPhone.startsWith('55')) {
             const withNine = cleanPhone.slice(0, 4) + '9' + cleanPhone.slice(4);
             if (groupNumbers.has(withNine)) {
                 status = "NO GRUPO";
                 log = "Match com 9 dígito";
             }
        }
    }

    results.push({
        json: {
            row_number: row.row_number,
            TelefoneOriginal: originalPhone,
            TelefoneFormatado: cleanPhone,
            Saida: status,
            Enviado: "SIM",
            LogMatch: log
        }
    });
}

return results;
